pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address addr, uint256 amount1, uint256 amount2) public {
        // Restrict addr to something that can receive Ether and avoid system contracts
        vm.assume(addr != address(this) && addr != address(0) && amount1 > 0 && amount2 > 0);
        // Bound amounts so total doesn't always overflow in test setup
        amount1 = bound(amount1, 1, type(uint128).max);
        amount2 = bound(amount2, 1, type(uint128).max);

        // Deposit first amount
        vm.deal(addr, amount1);
        vm.prank(addr);
        c.addToBalance{value: amount1}();

        // Record balance after first deposit
        uint256 balanceAfter1 = c.getBalance(addr);

        // Deposit second amount
        vm.deal(addr, amount2);
        vm.prank(addr);
        c.addToBalance{value: amount2}();

        uint256 balanceAfter2 = c.getBalance(addr);

        // General rule: balance must be monotonic and at least the sum of valid deposits.
        // After two deposits, balance should be >= the max individual deposit and > than after first.
        assertTrue(balanceAfter2 >= balanceAfter1 && balanceAfter2 >= amount1 + amount2);
    }
}

