pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        // Ensure actor is not address(0) to avoid problematic selfdestruct/precompile calls
        vm.assume(actor != address(0));
        // Bound amount to a reasonable range; we need enough to fund + withdraw and handle possible gas stipend
        bound(amount, 1, type(uint128).max);

        // 1. Fund the contract and actor, then add to balance
        vm.deal(actor, amount);
        vm.startPrank(actor);
        c.addToBalance{value: amount}();
        vm.stopPrank();

        // 2. Make the external call revert. We deploy a malicious receiver that reverts in fallback/receive.
        RevertingReceiver receiver = new RevertingReceiver();
        // The actor is now the receiver; we need to set its balance in C
        // We can't directly set mapping, so we transfer ETH to C on behalf of receiver,
        // then receiver calls addToBalance to have a non-zero balance.
        vm.deal(address(receiver), amount);
        vm.prank(address(receiver));
        c.addToBalance{value: amount}();

        // Record balance before withdraw
        uint256 balanceBefore = c.getBalance(address(receiver));
        require(balanceBefore > 0, "setup failed");

        // 3. Invoke withdrawBalance as the receiver. The receiver's fallback will revert.
        vm.prank(address(receiver));
        try c.withdrawBalance() {
            // Execution should not reach here because receiver reverts
            assertTrue(false, "withdrawBalance should have reverted");
        } catch {
            // Expected: external call reverted
        }

        // 4. GENERAL RULE: after withdrawBalance (whether revert or not), the caller's
        // recorded balance in getBalance MUST be 0.
        uint256 balanceAfter = c.getBalance(address(receiver));
        assertTrue(balanceAfter == 0, "balance not zeroed after withdraw attempt");
    }
}

