pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialBalance, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(initialBalance > 0);
        vm.assume(withdrawAmount <= initialBalance);

        // Set up actor with initial balance in the contract
        vm.deal(actor, 0);
        vm.prank(actor);
        c.addToBalance{value: initialBalance}();

        // Deploy a malicious contract that reverts on receive to trigger the external call failure
        RevertingReceiver receiver = new RevertingReceiver();
        vm.deal(address(receiver), 0);

        // Transfer the balance to the receiver so that its receive() reverts
        // First, we need the receiver to be the msg.sender with a balance
        // We'll make the receiver add to its balance first
        vm.prank(address(receiver));
        c.addToBalance{value: initialBalance}();

        // Now the receiver has the balance and will try to withdraw, causing its receive to revert
        bool ok = true;
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: if the external call during withdrawal fails,
        // the contract must revert and the caller's balance must remain unchanged.
        // We check: if the call reverted (ok == false), then getBalance(receiver) > 0.
        assertTrue(!(!ok && c.getBalance(address(receiver)) == 0));
    }
}

contract RevertingReceiver {
    receive() external payable {
        revert("revert on receive to test failure case");
    }
}
